import ReactDOM from "react-dom";
import React, { PureComponent } from "react";

class App extends PureComponent {
    constructor(props) {
        super(props);
        this.state = {
            defaultImage: 'data:image/jpeg;base64,',
            defaultImage1: 'data:image/jpeg;base64,',
            croppedImageUrl: null
        };

        this.createImages = this.createImages.bind(this);
        this.handleOnClick = this.handleOnClick.bind(this);
        this.hanldeOnSelect = this.hanldeOnSelect.bind(this);
    }

    handleOnClick(src) {
        this.setState({ croppedImageUrl: src })
    }

    hanldeOnSelect() {
        window.top.createProfilePicturePopup.onClosing(this.state.croppedImageUrl);
    }

    createImages() {
        let images = [];
        const style4 = {
            width: '120px',
            height: '120px',
            padding: '4px'
        };

        const { imagesList } = this.props;
        for (let i = 0; length; i++) {
            const src = imagesList[i];
            images.push(<img style={style4} alt="Crop" onClick={() => this.handleOnClick(src)} src={src} />)
        }

        return images;
    }

    render() {
        const style2 = {
            display: 'block'
        };

        const style3 = {
            height: '500px',
            overflow: 'auto',
            marginBottom: '10px'
        };
        return (
            <div className="App">
                <div style={style2}>
                    <span>Picture Library</span>
                    <div style={style3}>
                        {this.createImages()}
                   
                    </div>
                </div>

                <div>
                    <button onClick={this.hanldeOnSelect}>Select</button>
                </div>
            </div>
        );
    }
}

export default App;

export const renderApp = (imagesList) => {
    ReactDOM.render(
        <App imagesList={imagesList}/>,
        document.getElementById('root')
    );
};

window.renderApp = renderApp;